import React from 'react';
import { Link } from 'react-router-dom';
import FAQItem from './FAQItem';
import styles from './FAQ.module.css';

const FAQ: React.FC = () => {
    const faqData = [
        {
            question: "What are Lightning with Moonlime Spark?",
            answer: "Lightning with Moonlime Spark is our revolutionary new technology that enables ultra-fast crypto transactions with minimal fees. It combines advanced blockchain protocols with our proprietary Spark infrastructure to deliver instant settlement and enhanced security features for all your digital asset transactions."
        },
        {
            question: "How do I create an account on Coin Vault?",
            answer: "Creating an account on BlockCoinY is simple and secure. Click 'Sign Up', provide your email address and create a strong password. Complete the verification process by confirming your email and providing required identification documents. Once verified, you can start trading immediately with full access to all platform features.",
            isExpanded: true
        },
        {
            question: "Is Coin Vault secure?",
            answer: "Yes, BlockCoinY implements bank-level security measures including end-to-end encryption, two-factor authentication, cold storage for digital assets, and regular security audits. Your funds are protected by industry-leading security protocols and insurance coverage."
        },
        {
            question: "Do you offer customized marketing solutions?",
            answer: "Yes, we provide comprehensive marketing solutions tailored to your business needs. Our services include API integration, white-label solutions, institutional trading tools, and dedicated account management for high-volume traders and businesses."
        },
        {
            question: "What is MixtFlow and why is it the best website builder?",
            answer: "MixtFlow is our integrated trading interface that provides the most intuitive and powerful crypto trading experience. It features real-time market data, advanced charting tools, automated trading strategies, and seamless portfolio management - all designed to help you make better trading decisions."
        }
    ];

    return (
        <section className={styles.faq}>
            <div className={styles.container}>
                <div className={styles.content}>
                    <div className={styles.header}>
                        <h2 className={styles.title}>Frequently Asked Questions</h2>
                        <p className={styles.description}>
                            Get answers to the most common questions about our platform, 
                            security measures, and trading features.
                        </p>
                    </div>
                    
                    <div className={styles.faqGrid}>
                        <div className={styles.faqList}>
                            {faqData.map((item, index) => (
                                <FAQItem 
                                    key={index} 
                                    question={item.question} 
                                    answer={item.answer}
                                    isInitiallyExpanded={item.isExpanded || false}
                                />
                            ))}
                        </div>
                        
                        <div className={styles.ctaSection}>
                            <div className={styles.ctaCard}>
                                <h3 className={styles.ctaTitle}>
                                    Start Your Crypto Journey Today
                                </h3>
                                <p className={styles.ctaDescription}>
                                    Join a growing community of digital pioneers, navigate your assets, 
                                    explore innovations that will put the potential of crypto at your fingertips.
                                </p>
                                <Link to="/login" className={styles.ctaButton}>
                                    Get Started →
                                </Link>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </section>
    );
};

export default FAQ;
