import React, { ReactElement } from 'react';
import { motion } from 'framer-motion';
import styles from './ProductCard.module.css';

interface ProductCardProps {
    title: string;
    description: string;
    icon: ReactElement;
}

const ProductCard: React.FC<ProductCardProps> = ({ title, description, icon }) => {

    // Animation variants for Framer Motion
    const cardVariants = {
        initial: { 
            opacity: 0, 
            y: 50,
            scale: 0.95 
        },
        animate: { 
            opacity: 1, 
            y: 0,
            scale: 1,
            transition: {
                duration: 0.6,
                ease: "easeOut" as const
            }
        },
        hover: {
            y: -12,
            scale: 1.02,
            transition: {
                duration: 0.3,
                ease: "easeOut" as const
            }
        }
    };

    const iconVariants = {
        initial: { scale: 0, rotate: -180 },
        animate: { 
            scale: 1, 
            rotate: 0,
            transition: {
                delay: 0.3,
                duration: 0.5,
                ease: "backOut" as const
            }
        },
        hover: {
            scale: 1.1,
            rotate: 5,
            transition: {
                duration: 0.2
            }
        }
    };

    const contentVariants = {
        initial: { opacity: 0, y: 20 },
        animate: { 
            opacity: 1, 
            y: 0,
            transition: {
                delay: 0.4,
                duration: 0.4
            }
        }
    };

    return (
        <motion.div 
            className={styles.productCard}
            variants={cardVariants}
            initial="initial"
            animate="animate"
            whileHover="hover"
            whileTap={{ scale: 0.98 }}
            role="article"
            aria-labelledby={`product-title-${title.replace(/\s+/g, '-').toLowerCase()}`}
            aria-describedby={`product-desc-${title.replace(/\s+/g, '-').toLowerCase()}`}
            tabIndex={0}
            onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    // Handle card activation
                    console.log(`${title} card activated`);
                }
            }}
        >
            <div className={styles.iconContainer}>
                <motion.div 
                    className={styles.productIcon}
                    variants={iconVariants}
                    aria-label={`${title} icon`}
                >
                    {icon}
                </motion.div>
            </div>
            
            <motion.div 
                className={styles.content}
                variants={contentVariants}
            >
                <h3 
                    className={styles.productTitle}
                    id={`product-title-${title.replace(/\s+/g, '-').toLowerCase()}`}
                >
                    {title}
                </h3>
                <p 
                    className={styles.productDescription}
                    id={`product-desc-${title.replace(/\s+/g, '-').toLowerCase()}`}
                >
                    {description}
                </p>
            </motion.div>

            {/* Interactive glow effect */}
            <div className={styles.glowEffect} aria-hidden="true" />
            
            {/* Accessibility indicator */}
            <motion.div 
                className={styles.focusIndicator}
                initial={{ opacity: 0 }}
                whileFocus={{ opacity: 1 }}
                aria-hidden="true"
            />
        </motion.div>
    );
};

export default ProductCard;
