import React from 'react';
import styles from './Stats.module.css';

const Stats: React.FC = () => {
    const stats = [
        {
            number: "70M",
            label: "Sold Crypto",
            trend: "up",
            description: "Total cryptocurrency sold on our platform"
        },
        {
            number: "50%",
            label: "Increase",
            trend: "up", 
            description: "Average portfolio growth"
        },
        {
            number: "20K",
            label: "Happy Clients",
            trend: "stable",
            description: "Satisfied customers worldwide"
        }
    ];

    return (
        <section className={styles.statsSection}>
            <div className={styles.container}>
                <div className={styles.header}>
                    <span className={styles.sectionTag}>OUR ACHIEVEMENTS</span>
                    <h2 className={styles.title}>
                        Trusted by Millions of 
                        <span className={styles.highlight}> Crypto Investors</span>
                    </h2>
                    <p className={styles.description}>
                        Join the community that's reshaping the future of digital finance
                    </p>
                </div>
                
                <div className={styles.statsGrid}>
                    {stats.map((stat, index) => (
                        <div key={index} className={styles.statCard}>
                            <div className={styles.statNumber}>
                                {stat.number}
                                <span className={styles.statTrend}>
                                    {stat.trend === 'up' ? '📈' : '📊'}
                                </span>
                            </div>
                            <h3 className={styles.statLabel}>{stat.label}</h3>
                            <p className={styles.statDescription}>{stat.description}</p>
                        </div>
                    ))}
                </div>
            </div>
        </section>
    );
};

export default Stats;
