import React from 'react';
import { motion } from 'framer-motion';
import styles from './Features.module.css';

const Features: React.FC = () => {
    const features = [
        {
            icon: "⚡",
            title: "Lightning-Fast Execution",
            description: "Execute trades instantly with our cutting-edge technology and superior infrastructure.",
            ariaLabel: "Fast execution feature"
        },
        {
            icon: "🛡️", 
            title: "Bank-Level Security",
            description: "Your assets are protected with end-to-end encryption and two-factor authentication.",
            ariaLabel: "Security feature"
        },
        {
            icon: "💬",
            title: "24/7 Live Support", 
            description: "Get instant help from our expert team whenever you need assistance with your trades.",
            ariaLabel: "Support feature"
        },
        {
            icon: "💰",
            title: "Industry Low Fees",
            description: "Trade with confidence knowing you're getting the most competitive rates in the market.",
            ariaLabel: "Low fees feature"
        }
    ];

    const containerVariants = {
        hidden: { opacity: 0 },
        visible: {
            opacity: 1,
            transition: {
                staggerChildren: 0.1,
                delayChildren: 0.2
            }
        }
    };

    const itemVariants = {
        hidden: { opacity: 0, y: 20 },
        visible: { 
            opacity: 1, 
            y: 0,
            transition: {
                duration: 0.6
            }
        }
    };

    const cardVariants = {
        hidden: { opacity: 0, scale: 0.9 },
        visible: { 
            opacity: 1, 
            scale: 1,
            transition: {
                duration: 0.5
            }
        }
    };

    return (
        <motion.section 
            className={styles.features}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, amount: 0.3 }}
            variants={containerVariants}
            role="region"
            aria-labelledby="features-title"
        >
            <div className={styles.container}>
                <motion.div className={styles.header} variants={itemVariants}>
                    <span className={styles.sectionTag} aria-hidden="true">WHY CHOOSE US</span>
                    <h2 id="features-title" className={styles.title}>
                        Trade Smarter With 
                        <span className={styles.highlight}> Powerful, Secure Tools</span>
                    </h2>
                    <p className={styles.description}>
                        Experience the next generation of crypto trading with our advanced platform 
                        designed for both beginners and professional traders.
                    </p>
                </motion.div>
                
                <motion.div 
                    className={styles.featuresGrid}
                    variants={containerVariants}
                >
                    {features.map((feature, index) => (
                        <motion.div 
                            key={index} 
                            className={styles.featureCard}
                            variants={cardVariants}
                            whileHover={{ 
                                scale: 1.05,
                                y: -5,
                                boxShadow: "0 20px 40px rgba(59, 130, 246, 0.2)"
                            }}
                            whileTap={{ scale: 0.98 }}
                            transition={{ type: "spring", stiffness: 300 }}
                            role="article"
                            aria-labelledby={`feature-title-${index}`}
                            tabIndex={0}
                        >
                            <motion.div 
                                className={styles.featureIcon}
                                aria-hidden="true"
                                whileHover={{ rotate: [0, -10, 10, 0] }}
                                transition={{ duration: 0.4 }}
                            >
                                {feature.icon}
                            </motion.div>
                            <h3 
                                id={`feature-title-${index}`}
                                className={styles.featureTitle}
                            >
                                {feature.title}
                            </h3>
                            <p className={styles.featureDescription}>
                                {feature.description}
                            </p>
                        </motion.div>
                    ))}
                </motion.div>
            </div>
        </motion.section>
    );
};

export default Features;
