
import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import styles from './Hero.module.css';

const Hero: React.FC = () => {
  // Array of crypto-related statistics
  const [currentStat, setCurrentStat] = useState(0);
  const stats = [
    { number: "120K+", label: "Active Users", trend: "up" },
    { number: "70M", label: "Sold Crypto", trend: "up" },
    { number: "50%", label: "Increase", trend: "up" },
    { number: "20K", label: "Happy Clients", trend: "stable" }
  ];

  // Rotate stats every 3 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentStat((prev) => (prev + 1) % stats.length);
    }, 3000);
    return () => clearInterval(interval);
  }, [stats.length]);

  // Animation variants
  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.2,
        delayChildren: 0.1
      }
    }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: { opacity: 1, y: 0 }
  };

  const floatingVariants = {
    float: {
      y: [0, -10, 0],
      transition: {
        duration: 3,
        repeat: Infinity,
        ease: "easeInOut"
      }
    }
  };

  return (
    <motion.section 
      className={styles.hero}
      initial="hidden"
      animate="visible"
      variants={containerVariants}
      role="banner"
      aria-labelledby="hero-title"
    >
      <div className={styles.hero__container}>
        <motion.div className={styles.hero__content} variants={itemVariants}>
          {/* User Stats Badge */}
          <motion.div 
            className={styles.hero__badge}
            variants={itemVariants}
            whileHover={{ scale: 1.05 }}
            transition={{ type: "spring", stiffness: 300 }}
          >
            <div className={styles.hero__userAvatars}>
              <div className={styles.avatar} aria-hidden="true"></div>
              <div className={styles.avatar} aria-hidden="true"></div>
              <div className={styles.avatar} aria-hidden="true"></div>
            </div>
            <AnimatePresence mode="wait">
              <motion.span 
                key={currentStat}
                className={styles.hero__badgeText}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                transition={{ duration: 0.3 }}
                aria-live="polite"
                aria-atomic="true"
              >
                {stats[currentStat].number} ⭐ {stats[currentStat].label}
              </motion.span>
            </AnimatePresence>
          </motion.div>

          {/* Main Headlines */}
          <motion.h1 
            id="hero-title"
            className={styles.hero__title}
            variants={itemVariants}
          >
            Trade Crypto Instantly 
            <span className={styles.hero__highlight}> With Confidence</span>
          </motion.h1>
          
          <motion.h2 
            className={styles.hero__subtitle}
            variants={itemVariants}
          >
            Join the leading platform to buy, sell and exchange digital assets securely.
          </motion.h2>
          
          <motion.p 
            className={styles.hero__description}
            variants={itemVariants}
          >
            Join a growing community of digital pioneers, navigate your assets, 
            explore innovations that will put the potential of crypto journey at your fingertips.
          </motion.p>

          {/* CTA Button */}
          <motion.div 
            className={styles.hero__actions}
            variants={itemVariants}
          >
            <motion.div
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              transition={{ type: "spring", stiffness: 300 }}
            >
              <Link 
                to="/signup" 
                className={styles.hero__ctaButton}
                aria-label="Start conversation with our team"
              >
                Let's Talk 💬
              </Link>
            </motion.div>
            <motion.div
              whileHover={{ scale: 1.05, x: 5 }}
              whileTap={{ scale: 0.95 }}
              transition={{ type: "spring", stiffness: 300 }}
            >
              <Link 
                to="/login"
                className={styles.hero__secondaryButton}
                aria-label="Get started with crypto trading"
              >
                Get Started →
              </Link>
            </motion.div>
          </motion.div>
        </motion.div>

        {/* Mobile App Mockup */}
        <motion.div 
          className={styles.hero__visual}
          variants={itemVariants}
        >
          <motion.div 
            className={styles.hero__phoneContainer}
            whileHover={{ scale: 1.02, rotateY: 5 }}
            transition={{ type: "spring", stiffness: 300 }}
          >
            <div className={styles.hero__phone}>
              <div className={styles.hero__phoneScreen}>
                <div className={styles.hero__appInterface}>
                  <div className={styles.hero__appHeader}>
                    <div className={styles.hero__userInfo}>
                      <div className={styles.hero__userAvatar} aria-hidden="true">👤</div>
                      <div>
                        <span className={styles.hero__greeting}>Hello, Kabir</span>
                        <div className={styles.hero__balance}>
                          <span className={styles.hero__balanceLabel}>Current Balance</span>
                          <motion.span 
                            className={styles.hero__balanceAmount}
                            initial={{ opacity: 0, scale: 0.8 }}
                            animate={{ opacity: 1, scale: 1 }}
                            transition={{ delay: 1, duration: 0.5 }}
                          >
                            $9,650.00
                          </motion.span>
                        </div>
                      </div>
                    </div>
                    <div className={styles.hero__notificationIcon} aria-hidden="true">🔔</div>
                  </div>
                  
                  <div className={styles.hero__appActions}>
                    <motion.div 
                      className={styles.hero__actionButton}
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}
                      role="button"
                      tabIndex={0}
                      aria-label="Withdraw funds"
                    >
                      <span className={styles.hero__actionIcon} aria-hidden="true">💳</span>
                      <span>Withdraw</span>
                    </motion.div>
                    <motion.div 
                      className={styles.hero__actionButton}
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}
                      role="button"
                      tabIndex={0}
                      aria-label="Deposit funds"
                    >
                      <span className={styles.hero__actionIcon} aria-hidden="true">📈</span>
                      <span>Deposit</span>
                    </motion.div>
                  </div>

                  <div className={styles.hero__holdings}>
                    <h3>Holdings</h3>
                    <div className={styles.hero__coinList}>
                      <motion.div 
                        className={styles.hero__coinItem}
                        whileHover={{ scale: 1.02, backgroundColor: "rgba(59, 130, 246, 0.1)" }}
                        transition={{ duration: 0.2 }}
                      >
                        <span className={styles.hero__coinIcon} aria-hidden="true">🔶</span>
                        <span className={styles.hero__coinName}>Ethereum</span>
                        <span className={styles.hero__coinPrice}>$3,053.59</span>
                      </motion.div>
                      <motion.div 
                        className={styles.hero__coinItem}
                        whileHover={{ scale: 1.02, backgroundColor: "rgba(59, 130, 246, 0.1)" }}
                        transition={{ duration: 0.2 }}
                      >
                        <span className={styles.hero__coinIcon} aria-hidden="true">🟡</span>
                        <span className={styles.hero__coinName}>Bitcoin</span>
                        <span className={styles.hero__coinPrice}>$45,678</span>
                      </motion.div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </motion.div>

          {/* Floating Crypto Elements */}
          <div className={styles.hero__floatingElements} aria-hidden="true">
            <motion.div 
              className={`${styles.hero__floatingCoin} ${styles.hero__ethereum}`}
              animate={{
                y: [0, -10, 0],
              }}
              transition={{
                duration: 3,
                repeat: Infinity,
                ease: "easeInOut",
                delay: 0
              }}
            >
              <span className={styles.hero__coinSymbol}>⟐</span>
              <span className={styles.hero__coinLabel}>Ethereum</span>
              <span className={styles.hero__coinTrend}>📈</span>
            </motion.div>
            <motion.div 
              className={`${styles.hero__floatingCoin} ${styles.hero__bitcoin}`}
              animate={{
                y: [0, -10, 0],
              }}
              transition={{
                duration: 3,
                repeat: Infinity,
                ease: "easeInOut",
                delay: 1
              }}
            >
              <span className={styles.hero__coinSymbol}>₿</span>
              <span className={styles.hero__coinLabel}>Bitcoin</span>
              <span className={styles.hero__coinTrend}>🔒</span>
            </motion.div>
            <motion.div 
              className={`${styles.hero__floatingCoin} ${styles.hero__cardano}`}
              animate={{
                y: [0, -10, 0],
              }}
              transition={{
                duration: 3,
                repeat: Infinity,
                ease: "easeInOut",
                delay: 2
              }}
            >
              <span className={styles.hero__coinSymbol}>₳</span>
              <span className={styles.hero__coinLabel}>Cardano</span>
              <span className={styles.hero__coinTrend}>⚡</span>
            </motion.div>
          </div>
        </motion.div>
      </div>
    </motion.section>
  );
};

export default Hero;
